ead:after{right:23%}.hair-top{position:absolute;width:31%;height:11%;left:34.5%;top:8.5%;border-radius:70% 70% 30% 20%;background:#6d4052;z-index:3}.body{position:absolute;width:56%;height:43%;left:22%;bottom:2%;z-index:2}.shirt{position:absolute;width:76%;height:43%;left:12%;top:0;border-radius:48% 48% 14% 14%;background:linear-gradient(135deg,#ff9fc5,#ed6fa5);border:2px solid rgba(255,255,255,.15);z-index:3}.shorts{position:absolute;width:100%;height:52%;left:0;bottom:-2%;border-radius:32% 32% 44% 44%;background:#7773aa;z-index:4}.backdrop{position:absolute;width:74%;height:35%;left:13%;bottom:6%;border-radius:46%;background:#57456a;opacity:.9}.cushion-wrap{position:absolute;width:68%;height:36%;left:16%;bottom:4%;z-index:7}.cushion{position:absolute;width:66%;height:76%;bottom:0;border-radius:48% 48% 42% 42%;background:linear-gradient(145deg,#ed8bb5,#c76096);box-shadow:inset -12px -8px 20px rgba(110,45,82,.16),inset 10px 8px 18px rgba(255,212,230,.18),0 12px 20px rgba(0,0,0,.18);transition:transform .09s cubic-bezier(.2,.8,.2,1);cursor:pointer}.cushion.left{left:0;transform-origin:100% 70%;border-radius:55% 42% 44% 48%}.cushion.right{right:0;transform-origin:0 70%;border-radius:42% 55% 48% 44%}.cushion.pressed.left{transform:scale(.78,.58) translate(8%,8%)}.cushion.pressed.right{transform:scale(.78,.58) translate(-8%,8%)}.cushion-inner{position:absolute;width:62%;height:58%;left:19%;bottom:12%;border-radius:50%;border:1px solid rgba(255,255,255,.12)}.hands{position:absolute;z-index:10;width:44%;height:20%;left:28%;bottom:-2%;pointer-events:none}.hand{position:absolute;width:48%;height:78%;bottom:-10%;border-radius:48%;background:#e7a98d;opacity:0;transition:opacity .12s,transform .12s}.hand.left{left:2%;transform:rotate(-12deg)}.hand.right{right:2%;transform:rotate(12deg)}.character.show-hands .hand{opacity:1;transform:translateY(-32px) scale(.92)}.floor{position:absolute;width:80%;height:30%;left:10%;bottom:-12%;border-radius:50%;background:rgba(255,255,255,.035)}.combo{position:absolute;z-index:6;left:50%;top:64%;transform:translate(-50%,-50%) scale(.8);font-size:52px;font-weight:1000;font-style:italic;text-shadow:0 8px 24px #17152b;color:#ffd7ea;opacity:0;transition:.18s}.combo.pop{opacity:1;transform:translate(-50%,-50%) scale(1) rotate(-4deg)}.meterbox{position:absolute;z-index:8;left:50%;bottom:22px;transform:translateX(-50%);width:min(500px,70vw)}.meterlabel{display:flex;justify-content:space-between;margin-bottom:6px;font-size:10px;letter-spacing:2px;text-transform:uppercase;color:#aaa4be}.meter{height:10px;border-radius:20px;background:rgba(255,255,255,.09);overflow:hidden}.fill{height:100%;width:0;border-radius:20px;background:linear-gradient(90deg,#ff74b2,#ffd06a);transition:width .15s}.button{position:absolute;z-index:20;left:50%;top:50%;transform:translate(-50%,-50%);padding:16px 30px;border:0;border-radius:999px;background:#fff;color:#30243f;font-weight:900;font-size:16px;cursor:pointer;box-shadow:0 12px 40px rgba(0,0,0,.28)}.hidden{display:none}.spark{position:absolute;width:8px;height:8px;border-radius:50%;background:#ffd7ea;z-index:30;pointer-events:none;animation:spark .55s ease-out forwards}@keyframes spark{to{transform:translate(var(--dx),var(--dy)) scale(0);opacity:0}}@media(max-height:650px){.character{height:min(60vh,430px);width:min(50vw,360px)}.stage{inset:72px 0 0}.top{padding-top:12px}.meterbox{bottom:10px}.combo{top:58%}}@media(max-width:520px){.top{padding:12px 12px}.brand b{font-size:21px}.brand{font-size:11px}.stats{gap:5px}.pill{min-width:72px;padding:7px 8px}.pill strong{font-size:17px}.character{width:78vw;height:60vh;max-height:430px}.meterbox{width:82vw}.halo{width:92vw;height:92vw}}
