<body><div class="game"><div class="sun"></div><div class="top"><div class="brand">SQUISH<b>STUDIO</b></div><div class="stats"><div class="pill"><small>Score</small><strong id="score">0</strong></div><div class="pill"><small>Combo</small><strong id="combo">x1</strong></div></div></div><div class="stage"><div class="halo"></div><div class="floor"></div><div class="character" id="character"><div class="backdrop"></div><div class="hair"></div><div class="head"></div><div class="hair-top"></div><div class="body"><div class="shirt"></div><div class="shorts"></div></div><div class="cushion-wrap"><div class="cushion left" data-side="left"><div class="cushion-inner"></div></div><div class="cushion right" data-side="right"><div class="cushion-inner"></div></div></div><div class="hands"><div class="hand left"></div><div class="hand right"></div></div></div><div class="combo" id="comboText">SQUISH!</div></div><div class="meterbox"><div class="meterlabel"><span>Squish meter</span><span id="percent">0%</span></div><div class="meter"><div class="fill" id="fill"></div></div></div><button class="button" id="start">START SQUISHING</button></div>
<script>
const scoreEl=document.getElementById('score'),comboEl=document.getElementById('combo'),comboText=document.getElementById('comboText'),fill=document.getElementById('fill'),percent=document.getElementById('percent'),character=document.getElementById('character'),start=document.getElementById('start');let score=0,combo=1,active=false,meter=0,timeout;
function addSpark(el,x,y){for(let i=0;i<9;i++){const s=document.createElement('i');s.className='spark';s.style.left=x+'px';s.style.top=y+'px';const a=Math.PI*2*i/9,r=35+Math.random()*35;s.style.setProperty('--dx',Math.cos(a)*r+'px');s.style.setProperty('--dy',Math.sin(a)*r+'px');el.appendChild(s);setTimeout(()=>s.remove(),600)}}
function squish(e){if(!active)return;const el=e.currentTarget,rect=el.getBoundingRect?el.getBoundingRect():el.getBoundingClientRect();el.classList.add('pressed');character.classList.add('show-hands');clearTimeout(timeout);timeout=setTimeout(()=>{el.classList.remove('pressed');character.classList.remove('show-hands')},180);combo=Math.min(combo+1,99);score+=10*combo;meter=Math.min(100,meter+7);scoreEl.textContent=score.toLocaleString();comboEl.textContent='x'+combo;fill.style.width=meter+'%';percent.textContent=Math.round(meter)+'%';comboText.textContent=['SQUISH!','SOFT!','NICE!','BOING!','YEAH!'][Math.floor(Math.random()*5)];comboText.classList.remove('pop');void comboText.offsetWidth;comboText.classList.add('pop');setTimeout(()=>comboText.classList.remove('pop'),300);let x=e.clientX,y=e.clientY;if(!x){const r=rect;x=r.left+r.width/2;y=r.top+r.height/2}addSpark(document.querySelector('.game'),x,y)}
document.querySelectorAll('.cushion').forEach(c=>{c.addPointerCapture&&c.addEventListener('pointerdown',squish);c.addEventListener('contextmenu',e=>e.preventDefault())});
let decay=setInterval(()=>{if(active&&meter>0){meter=Math.max(0,meter-.18);fill.style.width=meter+'%';percent.textContent=Math.round(meter)+'%';combo=Math.max(1,combo-1);comboEl.textContent='x'+combo}},120);
start.addEventListener('click',()=>{active=true;score=0;combo=1;meter=0;scoreEl.textContent='0';comboEl.textContent='x1';fill.style.width='0';percent.textContent='0%';start.classList.add('hidden')});
</script></body></html>''')
